INSERT INTO tensor_maturity_verdicts (repo, scope, mission_id, level, evidence, verdict_by) VALUES ('TensorSPH', 'droplet_impact (main solver)', 14489, 3, '{"entry": "src/tensorsph/droplet_impact.py:run ; src/tensorsph/__main__.py:12 (CLI `python -m tensorsph`)", "executes": "torch WCSPH integration, 750 steps end-to-end (examples/droplet_impact_2d/run.py)", "integration": "exported in tensorsph/__init__.py __all__ (90 symbols); reused by 5+ modules and 20+ tests", "io": "diagnostic CSV + snapshots + JSON report + density figure", "case": "examples/droplet_impact_2d ; python -m tensorsph", "independent_benchmark": "NONE - README states ''not compared with experiment''; no experimental gate", "level_reason": "L3 = system integration: main integrator of the repo, CLI entry, reused across modules; no L4 because no benchmark-vs-reference comparison exists", "gaps": ["no experimental validation", "dt/kernel duplicated in wcsph and threed"]}'::jsonb, 'audit2-ab');
INSERT INTO tensor_maturity_verdicts (repo, scope, mission_id, level, evidence, verdict_by) VALUES ('TensorSPH', 'threed/ (3-D operators)', 14489, 3, '{"entry": "src/tensorsph/threed/solver.py:1 ; threed/kernel3.py:90 ; threed/operators3.py", "executes": "YES - own 3-D kernel/lattice/neighbour/force stack, separate from 2-D solver", "integration": "subpackage, not re-exported by top-level __init__", "io": "benchmarks/threed_{kernel,shear,hydrostatic}/report.json", "case": "benchmarks/threed_kernel/run.py --merge", "independent_benchmark": "YES analytic: unsteady-Stokes shear decay 2.7%, hydrostatic 2.7%, kernel 2nd moment", "audit_run": "RAN 2026-11-11: benchmarks/threed_kernel/run.py --merge -> 6/6 criteria pass in 10.9 s (artifacts/audit_m14489/threed_kernel.log)", "level_reason": "L3: verified operator stack with reproducible analytic anchors; L4 withheld because no free-surface/multiphase 3-D case exists (docs/verification_threed.md declares the limitation)"}'::jsonb, 'audit2-ab');
INSERT INTO tensor_maturity_verdicts (repo, scope, mission_id, level, evidence, verdict_by) VALUES ('TensorSPH', 'dam_break (2-D dam break)', 14489, 3, '{"entry": "src/tensorsph/dam_break.py:run_case ; exported top-level", "executes": "YES", "integration": "top-level API + used by freesurface/ritter_anchor.py:363", "io": "benchmarks/dam_break/*.json ; docs/reports/sph-verification-P482-N04.json", "case": "benchmarks/dam_break/experimental_validation.py ; benchmarks/verified/sph_dam_break_2d/run.py", "independent_benchmark": "PARTIAL WITHHELD: bundled Martin & Moyce table graded WITHHELD by repo''s own audit (benchmarks/dam_break/reference_audit.json); crosscheck table used", "gate_status": "FAIL: front_max_rel_error=0.7781 vs gate 0.10 (docs/reports/sph-verification-P482-N04.json M1.dam_break_2d.metrics.front_max_rel_error)", "level_reason": "L3: real solver + convergence ladder; not L4 because the experimental front gate fails at 77.8% and the primary reference is WITHHELD", "note": "README headline ''front converges at order 0.96'' refers to the Ritter self-similar solution, not to the experiment"}'::jsonb, 'audit2-ab');
